      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            <Link href={`/blog/${post.id}`}>{post.title}</Link>
          </li>
        ))}
      </ul>

      <NavigationButton href="/blog">View All Posts</NavigationButton>
    </div>
  )
}

