import type { NextRequest } from 'next/server'

import type { SimulatedPost, UpdatePostBody } from '@/types/api'

type RouteParams = { params: Promise<{ id: string }> }

function parseId(id: string): number | null {
  const n = parseInt(id, 10)
  return Number.isFinite(n) ? n : null
}

export async function GET(_request: NextRequest, context: RouteParams) {
  const { id: idParam } = await context.params
  const id = parseId(idParam)

  if (id === null) {
    return Response.json({ error: 'Invalid id' }, { status: 400 })
  }

  const post: SimulatedPost = {
    id,
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return Response.json(post)
}

export async function PUT(request: NextRequest, context: RouteParams) {
  const { id: idParam } = await context.params
  const id = parseId(idParam)

  if (id === null) {
    return Response.json({ error: 'Invalid id' }, { status: 400 })
  }

  let body: UpdatePostBody
  try {
    body = (await request.json()) as UpdatePostBody
  } catch {
    return Response.json({ error: 'Invalid JSON body' }, { status: 400 })
  }

  const { title, content } = body

  const updatedPost: SimulatedPost = {
    id,
    title: title ?? `Post ${id}`,
    content: content ?? `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return Response.json(updatedPost)
}

export async function DELETE(_request: NextRequest, context: RouteParams) {
  const { id: idParam } = await context.params
  const id = parseId(idParam)

  if (id === null) {
    return Response.json({ error: 'Invalid id' }, { status: 400 })
  }

  return Response.json({ message: `Post ${id} deleted successfully` })
}

