        return null
      }

      const [post, comments] = await Promise.all([
        postRes.json() as Promise<JsonPlaceholderPost>,
        commentsRes.ok
          ? (commentsRes.json() as Promise<JsonPlaceholderComment[]>)
          : Promise.resolve([] as JsonPlaceholderComment[]),
      ])

      return { post, comments }
    } catch {
      return null
    }
  }
)

export async function generateMetadata({
  params,
}: BlogPostPageProps): Promise<Metadata> {
  const { id } = await params
  const data = await loadPostData(id)

  if (!data) {
    return { title: 'Post' }
  }

  const { post } = data
  const description = post.body.substring(0, 160)

  return {
    title: post.title,
    description,
    openGraph: {
      title: post.title,
      description,
    },
  }
}

export default async function BlogPostPage({ params }: BlogPostPageProps) {
  const { id } = await params
  const data = await loadPostData(id)

  if (!data) {
    notFound()
  }

  const { post, comments } = data

  return (
    <article>
      <BackButton>← Back</BackButton>

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

